				"**七杀（庙旺）** 在夫妻宫：",
				"夫妻宫七杀，配偶个性强势，处事果决，感情激烈，婚姻中多冲突与拉锯。需更多耐心与包容，给彼此足够的自主空间；双方都需学会退一步，否则家庭多争执，难以平和。若三方有吉化加持，则强强联合，共同成就更多。",
				"**破军化禄（落陷）** 在夫妻宫：",
				"✦ 右弼：配偶温柔体贴，婚姻以情义为基。",
				"✦ 禄存：配偶稳健理财，婚姻以稳为主。",
				"**廉贞化禄（庙旺）** 在夫妻宫：",
				"夫妻宫廉贞，感情激烈而波折，配偶有才艺与魅力，但桃花重，需防第三者介入或感情纠纷。婚姻中激情与矛盾并存，需要双方都具备包容度。化禄则才艺加持，感情顺遂，人脉带来好的姻缘。",
				"▶ 化禄：化禄，才艺与人脉带来财禄，桃花化为助力，感情顺遂，贵人多相助，是廉贞较好的格局。",
				"✦ 文曲：配偶感性细腻，善表达，感情中言语沟通是关键。",
				"**廉贞化禄** 在夫妻宫：",
				"**廉贞化禄（落陷）** 在夫妻宫：",
				"**贪狼（落陷）** 在夫妻宫：",
				"**破军化权（落陷）** 在夫妻宫：",
				"夫妻宫破军，感情多变动，非传统型婚姻关系较多，可能有多段感情经历，或与配偶有年龄差距。需给彼此足够自由，否则关系难以长久。",
				"▶ 化权：化权，破坏力化为创造力，在所在领域开疆拓土，是先锋精神与掌控力的结合。",
				"**破军化权（庙旺）** 在夫妻宫：",
