				"夫妻宫廉贞，感情激烈而波折，配偶有才艺与魅力，但桃花重，需防第三者介入或感情纠纷。婚姻中激情与矛盾并存，需要双方都具备包容度。化忌时血光或官非与感情相关，严重时可能有大的婚姻变故，须用心经营切忌意气用事。",
				"▶ 化忌：化忌，血光官非风险极大，感情纠纷多，是较为严重的凶象，须特别谨慎，避免冲动行事。",
